<style lang="scss" scoped src="./transaction-detail-block.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { format } from "date-fns";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { has } from "../../util/has";
import { currencyFormat } from "../../util/currency-format";
import Icon from "../../components/icon/icon";
import { IconShape } from "../../components/icon/icon.constants";

@Component({
  components: {
    Icon,
  },
})
export default class TransactionDetailBlock extends Vue {
  @Prop({
    type: String,
    default: "",
  })
  status;

  @Prop({
    type: Date,
    default: new Date(),
  })
  createdTime;

  @Prop({
    type: String,
    default: "",
  })
  type;

  @Prop({
    type: String,
    default: "",
  })
  description;

  /**
    {
      type: String;  // visa, masterCard, discover...
      lastFourDigit: Number;
      image: String;
      expireDate: Date;
    }
   */
  @Prop({
    type: Object,
    default: () => {},
  })
  cardInfo;

  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues),
  })
  currency;

  @Prop({
    type: String,
    default: "",
  })
  orgName;

  @Prop({
    type: String,
    default: "",
  })
  orgId;

  @Prop({
    type: String,
    default: "",
  })
  campaign;

  @Prop({
    type: String,
    default: "",
  })
  designation;

  @Prop({
    type: String,
    default: "-",
  })
  notes;

  @Prop({
    type: String,
    default: "",
  })
  desNote;

  @Prop({
    type: Number,
    default: 0,
  })
  netProceed;

  @Prop({
    type: Number,
    default: 0,
  })
  charityProceed;

  @Prop({
    type: String,
    default: "",
  })
  frequency;

  @Prop({
    type: Number,
    default: 0,
  })
  recurringCount;

  @Prop({
    type: String,
    default: "",
  })
  schedule;

  @Prop({
    type: String,
    default: "",
  })
  paymentId;

  IconShape = IconShape;

  get formattedTime() {
    return format(this.createdTime, "MM-dd-y hh:mm a");
  }

  get cardSummary() {
    return `****${this.cardInfo.lastFourDigit} Exp ${format(
      this.cardInfo.expireDate,
      "MM/y"
    )}`;
  }

  get cardImage() {
    return {
      backgroundImage: `url(${this.cardInfo.image})`,
    };
  }

  get formattedNetProceeds() {
    return `${this.currency}${currencyFormat(this.netProceed, true)}`;
  }

  get formattedCharityProceeds() {
    return `${this.currency}${currencyFormat(this.charityProceed, true)}`;
  }

  handleCopyOrgId() {
    try {
      const el = document.createElement("textarea");
      el.value = this.$refs.org.innerHTML;
      /**
       * Emits when the user clicks the copy icon/command next to the org ID.
       * The element should be copied to the clipboard but will emit this event
       * regardless in case there needs to be additional handling to get the
       * copy executed for the customer.
       *
       * @event copyOrg
       */
      this.$emit("copyOrg", el.value);
      el.setAttribute("readonly", "");
      el.style.position = "absolute";
      el.style.left = "-9999px";
      document.body.appendChild(el);
      el.select();
      document.execCommand("copy");
    } catch (err) {
      // Could not copy
    }
  }

  handleCopyPaymentId() {
    try {
      const el = document.createElement("textarea");
      el.value = this.$refs.payment.innerHTML;
      /**
       * Emits when the user clicks the copy icon/command next to the payment ID.
       * The element should be copied to the clipboard but will emit this event
       * regardless in case there needs to be additional handling to get the
       * copy executed for the customer.
       *
       * @event copyPayment
       */
      this.$emit("copyPayment", el.value);
      el.setAttribute("readonly", "");
      el.style.position = "absolute";
      el.style.left = "-9999px";
      document.body.appendChild(el);
      el.select();
      document.execCommand("copy");
    } catch (err) {
      // Could not copy
    }
  }

  handleClickField(field, value) {
    return () => {
      /**
       * Emits when the user clicks on a field in the panel, providing the field
       * name and value.
       *
       * @event clickField
       */
      this.$emit("clickField", field, value);
    };
  }
}
</script>

<template>
  <div class="TransactionDetailBlock">
    <div class="TransactionDetailBlock__Header">
      <div class="TransactionDetailBlock__Title">
        {{ "Transaction Details" }}
      </div>
      <div class="TransactionDetailBlock__HeaderRight">
        <h1>{{ "Status" }}</h1>
        <div class="TransactionDetailBlock__Status">{{ status }}</div>
      </div>
    </div>
    <div class="TransactionDetailBlock__Upper">
      <div class="TransactionDetailBlock__Row">
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('created', formattedTime)"
        >
          <h1>{{ "Created" }}</h1>
          <h2>{{ formattedTime }}</h2>
        </div>
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('type', type)"
        >
          <h1>{{ "Type" }}</h1>
          <h2>{{ type }}</h2>
        </div>
      </div>
      <div class="TransactionDetailBlock__Row">
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('description', description)"
        >
          <h1>{{ "Description" }}</h1>
          <h2>{{ description }}</h2>
        </div>
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('cardSummary', cardSummary)"
        >
          <div class="TransactionDetailBlock__Image" :style="cardImage" />
          <h2>{{ cardSummary }}</h2>
        </div>
      </div>
      <div class="TransactionDetailBlock__Row">
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('orgName', orgName)"
        >
          <h1>{{ "Org Name" }}</h1>
          <h2>{{ orgName }}</h2>
        </div>
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('orgId', orgId)"
        >
          <h1>{{ "Org ID" }}</h1>
          <h2 ref="org">{{ orgId }}</h2>
          <div class="TransactionDetailBlock__Copy" @click="handleCopyOrgId">
            <Icon :shape="IconShape.COPY" :size="16" :color="'#2356f6'" />
          </div>
        </div>
      </div>
    </div>
    <div class="TransactionDetailBlock__Middle">
      <div class="TransactionDetailBlock__Row">
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('campaign', campaign)"
        >
          <h1>{{ "Campaign" }}</h1>
          <h3 :style="{ cursor: 'pointer' }">{{ campaign }}</h3>
        </div>
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('designation', designation)"
        >
          <h1>{{ "Designation" }}</h1>
          <h3 :style="{ cursor: 'pointer' }">{{ designation }}</h3>
        </div>
      </div>
      <div class="TransactionDetailBlock__Row">
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('notes', notes)"
        >
          <h1>{{ "Notes" }}</h1>
          <h2>{{ notes }}</h2>
        </div>
        <div
          class="TransactionDetailBlock__Unit"
          @click="handleClickField('desNote', desNote)"
        >
          <h1>{{ "Des. Note" }}</h1>
          <h2>{{ desNote }}</h2>
        </div>
      </div>
    </div>
    <div class="TransactionDetailBlock__Lower">
      <div class="TransactionDetailBlock__Row">
        <div
          class="TransactionDetailBlock__LowerUnit"
          @click="handleClickField('netProceeds', formattedNetProceeds)"
        >
          <h1>{{ "Net Proceeds" }}</h1>
          <h4>{{ formattedNetProceeds }}</h4>
        </div>
        <div
          class="TransactionDetailBlock__LowerUnit"
          @click="handleClickField('charityProceeds', formattedCharityProceeds)"
        >
          <h1>{{ "Charity Proceeds" }}</h1>
          <h4>{{ formattedCharityProceeds }}</h4>
        </div>
      </div>
      <div class="TransactionDetailBlock__Row">
        <div
          class="TransactionDetailBlock__LowerUnit"
          @click="handleClickField('frequency', frequency)"
        >
          <h1>{{ "Frequency" }}</h1>
          <h4>{{ frequency }}</h4>
        </div>
        <div
          class="TransactionDetailBlock__LowerUnit"
          @click="handleClickField('recurringCount', recurringCount)"
        >
          <h1>{{ "Recurring Count" }}</h1>
          <h4>{{ recurringCount }}</h4>
        </div>
      </div>
      <div class="TransactionDetailBlock__Row">
        <div
          class="TransactionDetailBlock__LowerUnit"
          @click="handleClickField('schedule', schedule)"
        >
          <h1>{{ "Schedule" }}</h1>
          <h3 :style="{ cursor: 'pointer' }">{{ schedule }}</h3>
          <div class="TransactionDetailBlock__Arrow">
            <Icon :shape="IconShape.RIGHT" :size="9" :color="'#2356f6'" />
          </div>
        </div>
        <div
          class="TransactionDetailBlock__LowerUnit"
          @click="handleClickField('payment', paymentId)"
        >
          <h1>{{ "iDonate Payment ID" }}</h1>
          <h2 ref="payment">{{ paymentId }}</h2>
          <div
            class="TransactionDetailBlock__Copy"
            @click="handleCopyPaymentId"
          >
            <Icon :shape="IconShape.COPY" :size="16" :color="'#2356f6'" />
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
